import tempfile

import numpy as np
import pytest

from stem_gym.envs.stem_env import STEMEnv, ActionType
from stem_gym.envs.world import World
from stem_gym.tasks import DummyTask


# Path to test world — generated by data/scripts/generate_test_world.py
TEST_WORLD = Path(__file__).parent.parent / "data" / "simulated" / "test_world.h5"


@pytest.fixture(scope="module")
def world_path():
    """Ensure test world exists."""
    if not TEST_WORLD.exists():
        pytest.skip("Test world not generated. Run: python data/scripts/generate_test_world.py")
    return TEST_WORLD


@pytest.fixture
def env(world_path):
    """Create a fresh STEMEnv for each test."""
    e = STEMEnv(world_path, total_budget=1e4, max_steps=50)
    yield e
    e.close()


class TestWorldLoading:
    def test_world_opens(self, world_path):
        with World(world_path) as w:
            assert w.pixel_size_nm > 0
            assert w.tile_size_px > 0
            assert w.grid_shape[0] > 0
            assert w.grid_shape[1] > 0

    def test_get_tile(self, world_path):
        with World(world_path) as w:
            tile = w.get_tile(0, 0)
            assert tile.shape == (w.tile_size_px, w.tile_size_px)
            assert tile.dtype == np.float32

    def test_get_overview(self, world_path):
        with World(world_path) as w:
            overview = w.get_overview()
            assert overview.ndim == 2
            assert overview.dtype == np.float32

    def test_get_ground_truth(self, world_path):
        with World(world_path) as w:
            gt = w.get_ground_truth()
            assert "atom_positions" in gt
            assert "atom_types" in gt
            assert "defect_mask" in gt
            assert gt["atom_positions"].shape[1] == 2

    def test_nm_to_tile_roundtrip(self, world_path):
        with World(world_path) as w:
            row, col = 3, 5
            x_nm, y_nm = w.tile_to_nm(row, col)
            row2, col2 = w.nm_to_tile(x_nm, y_nm)
            assert row2 == row
            assert col2 == col


class TestObservationSpace:
    def test_reset_obs_matches_space(self, env):
        obs, info = env.reset(seed=42)
        assert env.observation_space.contains(obs), (
            f"Observation doesn't match space. Keys: {obs.keys()}"
        )

    def test_step_obs_matches_space(self, env):
        obs, _ = env.reset(seed=42)
        action = {
            "action_type": ActionType.NAVIGATE,
            "position": np.array([10.0, 10.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        obs, _, _, _, _ = env.step(action)
        assert env.observation_space.contains(obs)


class TestNavigate:
    def test_navigate_is_free(self, env):
        env.reset(seed=42)
        initial_dose = env.state.dose_used

        action = {
            "action_type": ActionType.NAVIGATE,
            "position": np.array([20.0, 20.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        env.step(action)

        assert env.state.dose_used == initial_dose, "Navigate should cost 0 dose"

    def test_navigate_updates_position(self, env):
        env.reset(seed=42)
        target = np.array([25.0, 30.0], dtype=np.float32)

        action = {
            "action_type": ActionType.NAVIGATE,
            "position": target,
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        env.step(action)

        assert np.allclose(env.state.position, (25.0, 30.0))


class TestAcquire:
    def test_acquire_costs_dose(self, env):
        env.reset(seed=42)
        initial_dose = env.state.dose_used

        action = {
            "action_type": ActionType.ACQUIRE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        env.step(action)

        assert env.state.dose_used > initial_dose, "Acquire should cost dose"

    def test_acquire_returns_nonzero_tile(self, env):
        env.reset(seed=42)

        action = {
            "action_type": ActionType.ACQUIRE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        obs, _, _, _, _ = env.step(action)

        assert obs["tile"].max() > 0, "Acquired tile should have nonzero data"

    def test_acquire_increments_tiles_acquired(self, env):
        env.reset(seed=42)
        assert env.state.tiles_acquired == 0

        action = {
            "action_type": ActionType.ACQUIRE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        env.step(action)

        assert env.state.tiles_acquired == 1

    def test_higher_dwell_costs_more(self, env):
        env.reset(seed=42)
        action = {
            "action_type": ActionType.ACQUIRE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        env.step(action)
        dose_1 = env.state.dose_used

        env.reset(seed=42)
        action["dwell"] = np.array([3.0], dtype=np.float32)
        env.step(action)
        dose_3 = env.state.dose_used

        assert dose_3 > dose_1, "Higher dwell should cost more dose"


class TestBudget:
    def test_budget_decrements(self, env):
        obs, _ = env.reset(seed=42)
        initial_budget = float(obs["budget_remaining"][0])
        assert initial_budget == pytest.approx(1.0)

        action = {
            "action_type": ActionType.ACQUIRE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        obs, _, _, _, _ = env.step(action)

        assert float(obs["budget_remaining"][0]) < initial_budget

    def test_budget_exhaustion_terminates(self):
        """Budget should terminate after a few acquires."""
        if not TEST_WORLD.exists():
            pytest.skip("Test world not generated")
        # 200 budget / 100 per acquire = exactly 2 acquires before budget hits 0
        e = STEMEnv(TEST_WORLD, total_budget=200.0, max_steps=1000)
        e.reset(seed=42)
        terminated = False
        for _ in range(1000):
            action = {
                "action_type": ActionType.ACQUIRE,
                "position": np.array([10.0, 10.0], dtype=np.float32),
                "zoom": np.array([1.0], dtype=np.float32),
                "dwell": np.array([1.0], dtype=np.float32),
                "finding_type": 0,
            }
            _, _, terminated, truncated, _ = e.step(action)
            if terminated or truncated:
                break
        e.close()
        assert terminated, "Budget exhaustion should terminate episode"


class TestEpisodeTermination:
    def test_done_action_terminates(self, env):
        env.reset(seed=42)
        action = {
            "action_type": ActionType.DONE,
            "position": np.array([0.0, 0.0], dtype=np.float32),
            "zoom": np.array([1.0], dtype=np.float32),
            "dwell": np.array([1.0], dtype=np.float32),
            "finding_type": 0,
        }
        _, _, terminated, _, _ = env.step(action)
        assert terminated

    def test_max_steps_truncates(self):
        """Episode truncates after max_steps."""
        if not TEST_WORLD.exists():
            pytest.skip("Test world not generated")
        e = STEMEnv(TEST_WORLD, total_budget=1e6, max_steps=5)
        e.reset(seed=42)
        truncated = False
        for _ in range(10):
            action = {
                "action_type": ActionType.NAVIGATE,
                "position": np.array([10.0, 10.0], dtype=np.float32),
                "zoom": np.array([1.0], dtype=np.float32),
                "dwell": np.array([1.0], dtype=np.float32),
                "finding_type": 0,
            }
            _, _, terminated, truncated, _ = e.step(action)
            if terminated or truncated:
                break
        e.close()
        assert truncated


class TestRandomAgent:
    def test_random_agent_100_episodes(self, env):
        """Random agent completes 100 episodes without errors."""
        rng = np.random.default_rng(42)

        for ep in range(100):
            obs, info = env.reset(seed=int(rng.integers(0, 2**31)))
            assert env.observation_space.contains(obs), f"Episode {ep}: reset obs invalid"

            for step in range(env._init_max_steps + 5):
                # Random action
                action_type = rng.integers(0, 4)
                fov_w, fov_h = env.world.fov_nm[1], env.world.fov_nm[0]
                action = {
                    "action_type": int(action_type),
                    "position": rng.uniform(
                        [0, 0], [fov_w, fov_h]
                    ).astype(np.float32),
                    "zoom": rng.uniform(1, 4, size=(1,)).astype(np.float32),
                    "dwell": rng.uniform(0.1, 10, size=(1,)).astype(np.float32),
                    "finding_type": int(rng.integers(0, 8)),
                }

                obs, reward, terminated, truncated, info = env.step(action)
                assert env.observation_space.contains(obs), (
                    f"Ep {ep}, step {step}: obs invalid"
                )

                if terminated or truncated:
                    break
